        // Ensure the caller is not the DAO (to test the bug)
        vm.assume(maliciousUser != originalDAO);
        vm.assume(maliciousUser != address(0));

        // Save current DAO address
        address daoBefore = c.DAO();

        // Drive assertGovernanceApproved — it will revert because asset transfer fails (no allowance)
        // We call from a governed address (the test contract itself via setUp) to satisfy the modifier
        // Actually, we need to make sender governed, but it's easier to wrap in try/catch
        // Alternatively, just call and it reverts; we want to observe state after revert.
        vm.prank(maliciousUser);
        try c.assertGovernanceApproved(maliciousUser, target, emergency) {
            // should not succeed because flash governance amount won't be transferred
            // but to be safe, handle both
        } catch {}

        // Check that setDAO can still be called by any caller (since configured is false)
        // The bug makes this revert, but the correct contract allows it.
        vm.prank(maliciousUser);
        bool setDaoSuccess;
        try c.setDAO(initialDAO) {
            setDaoSuccess = true;
        } catch {
