import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, address dao) public {
        vm.assume(dao != address(0));
        // Configure: set DAO to address(this) and then set configured=true via endConfiguration
        // But we want the rule when configured is false. Since constructor sets DAO to address(this), configured is false.
        // We'll prank as the current DAO (address(this)) to call assertGovernanceApproved first (which may succeed or revert)
        // Then we check that setDAO still works when caller is the current DAO or configured is false.
        // Simpler: after setUp, DAO = address(this), configured = false. We call assertGovernanceApproved with caller=this
        // then verify setDAO(caller) reverts only if caller is not the DAO.

        vm.assume(caller != address(0));

        // Step 1: call assertGovernanceApproved to potentially modify state (in reference, it may succeed with proper setup)
        // To make it simple, we can just try to call setDAO after the operation
        // The invariant: after any sequence of calls, setDAO should not revert when caller == DAO or configured is false

        // Direct test: call setDAO from a random caller, check if it reverts
        bool reverted;
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("setDAO(address)", dao));
        reverted = !success;

        // The rule: setDAO reverts only if caller is NOT the DAO AND configured is true
        // Since configured starts false and we never call endConfiguration, configured is always false
        // So setDAO should never revert.
        assertTrue(!reverted, "setDAO should not revert when configured is false");
    }
}

