        vm.prank(address(this)); // DAO is address(this)

        // Try the call and observe the revert behavior
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency)
        );

        // The rule: when emergency is false, the original (P) reverts, so success must be false
        // When emergency is true, both revert or both succeed depending on epoch
        assertTrue(!emergency || !success || emergency);
    }
}
